//! Investigation reports. Markdown and JSON are implemented; HTML/PDF can be added later by
//! implementing `ReportRenderer`.

use crate::files::{InvestigationFiles, StoredBlob, sha256_hex};
use crate::model::{Finding, Provenance, Workspace, now};
use crate::paths::sanitize_filename;
use crate::sanitize::sanitize_text;

pub fn render_markdown(workspace: &Workspace) -> String {
    let investigation = workspace.investigation();
    let mut out = String::new();
    out.push_str(&format!("# {}\n\n", investigation.name));
    out.push_str(&format!(
        "*Generated by os-int {} on {}.*\n\n",
        env!("CARGO_PKG_VERSION"),
        now().to_rfc3339()
    ));
    out.push_str("> AI-written analysis is labelled **AI inference (unverified)**. Claims that can be tied to a source keep their source IDs.\n\n");
    if !investigation.description.trim().is_empty() {
        out.push_str("## Executive Summary\n\n");
        out.push_str(&sanitize_text(&investigation.description));
        out.push_str("\n\n");
    }
    out.push_str("## Scope\n\n");
    if workspace.data.pages.is_empty() {
        out.push_str("No pages have been created yet.\n\n");
    } else {
        for page in &workspace.data.pages {
            out.push_str(&format!(
                "- {} {} ({}){}\n",
                page.short_ref(),
                page.title,
                page.kind.label(),
                page.target
                    .as_deref()
                    .map(|target| format!(" — `{target}`"))
                    .unwrap_or_default()
            ));
        }
        out.push('\n');
    }
    out.push_str("## Diagnostics\n\n");
    write_diagnostics(&mut out, workspace);
    out.push_str("## Key Findings\n\n");
    if workspace.data.findings.is_empty() {
        out.push_str("No findings recorded.\n\n");
    } else {
        for finding in &workspace.data.findings {
            write_finding(&mut out, workspace, finding);
        }
    }
    out.push_str("## Entities\n\n");
    for entity in &workspace.data.entities {
        out.push_str(&format!(
            "- {} [{}] {} ({})\n",
            entity.short_ref(),
            entity.kind.label(),
            entity.display_name(),
            entity.provenance.as_str()
        ));
    }
    if workspace.data.entities.is_empty() {
        out.push_str("None yet.\n");
    }
    out.push_str("\n## Infrastructure\n\n");
    write_infrastructure(&mut out, workspace);
    out.push_str("## Changes\n\n");
    write_changes(&mut out, workspace);
    out.push_str("## Timeline\n\n");
    if workspace.data.timeline.is_empty() {
        out.push_str("No dated events.\n\n");
    } else {
        for event in &workspace.data.timeline {
            out.push_str(&format!(
                "- {} {} — {} ({})\n",
                event.occurred_at.format("%Y-%m-%d"),
                event.short_ref(),
                sanitize_text(&event.title),
                event.kind.label()
            ));
        }
        out.push('\n');
    }
    out.push_str("## Evidence\n\n");
    for source in &workspace.data.sources {
        out.push_str(&format!(
            "### {} {}\n\n",
            source.short_ref(),
            sanitize_text(&source.title)
        ));
        out.push_str(&format!(
            "- Type: {}\n- Provenance: {}\n- Retrieved: {}\n",
            source.kind.label(),
            source.provenance.label(),
            source.retrieved_at.to_rfc3339()
        ));
        if let Some(url) = &source.url {
            out.push_str(&format!("- URL: {url}\n"));
        }
        if let Some(hash) = &source.content_hash {
            out.push_str(&format!("- SHA-256: `{hash}`\n"));
        }
        out.push('\n');
        if !source.content.trim().is_empty() {
            out.push_str("```\n");
            out.push_str(&sanitize_text(&source.content));
            if !source.content.ends_with('\n') {
                out.push('\n');
            }
            out.push_str("```\n\n");
        }
    }
    out.push_str("## Open Questions\n\n");
    let unsupported: Vec<&Finding> = workspace
        .data
        .findings
        .iter()
        .filter(|finding| finding.is_unsupported())
        .collect();
    if unsupported.is_empty() {
        out.push_str("No unsupported findings.\n\n");
    } else {
        for finding in unsupported {
            out.push_str(&format!(
                "- {} {} has no cited sources.\n",
                finding.short_ref(),
                finding.title
            ));
        }
        out.push('\n');
    }
    out.push_str("## Analyst Notes\n\n");
    let mut any_notes = false;
    for page in &workspace.data.pages {
        if !page.notes.trim().is_empty() {
            out.push_str(&format!(
                "### {}\n\n{}\n\n",
                page.title,
                sanitize_text(&page.notes)
            ));
            any_notes = true;
        }
    }
    for note in &workspace.data.notes {
        out.push_str(&format!(
            "- {} ({}) {}\n",
            note.short_ref(),
            note.provenance.as_str(),
            sanitize_text(note.headline())
        ));
        any_notes = true;
    }
    if !any_notes {
        out.push_str("None.\n\n");
    }
    out.push_str("## Sources\n\n");
    for source in &workspace.data.sources {
        out.push_str(&format!(
            "- [{}] {} ({})\n",
            source.short_ref(),
            sanitize_text(&source.title),
            source.provenance.as_str()
        ));
    }
    out
}

fn write_finding(out: &mut String, workspace: &Workspace, finding: &Finding) {
    let badge = match finding.provenance {
        Provenance::Agent => " — **AI inference (unverified)**",
        Provenance::Analyst => " — analyst",
        Provenance::Collected => " — collected",
        Provenance::External => " — original material",
    };
    let refs = workspace.format_source_refs(&finding.source_ids);
    out.push_str(&format!(
        "### {} {}\n\n{}  \nConfidence: {}{badge}  \nSources: {}\n\n",
        finding.short_ref(),
        sanitize_text(&finding.title),
        sanitize_text(&finding.details),
        finding.confidence.as_str(),
        if refs.is_empty() {
            "*(none)*".into()
        } else {
            refs
        }
    ));
}

fn write_diagnostics(out: &mut String, workspace: &Workspace) {
    let mut any = false;
    for entity in &workspace.data.entities {
        if let Some(posture) = entity.fields.get("diagnostics") {
            out.push_str(&format!(
                "- {} {} — {}\n",
                entity.short_ref(),
                sanitize_text(entity.display_name()),
                sanitize_text(posture)
            ));
            any = true;
        }
    }
    if !any {
        for source in &workspace.data.sources {
            if let Some(posture) = source.fields.get("diagnostics") {
                out.push_str(&format!(
                    "- {} {} — {}\n",
                    source.short_ref(),
                    sanitize_text(&source.title),
                    sanitize_text(posture)
                ));
                any = true;
            }
        }
    }
    if !any {
        out.push_str("No diagnostics recorded yet.\n");
    }
    out.push('\n');
}

fn write_changes(out: &mut String, workspace: &Workspace) {
    let mut any = false;
    for event in &workspace.data.timeline {
        if event.kind != crate::model::TimelineKind::Changed {
            continue;
        }
        out.push_str(&format!(
            "- {} {} — {}\n",
            event.occurred_at.format("%Y-%m-%d"),
            event.short_ref(),
            sanitize_text(&event.title)
        ));
        any = true;
    }
    if !any {
        out.push_str("No observation changes recorded.\n");
    }
    out.push('\n');
}

fn write_infrastructure(out: &mut String, workspace: &Workspace) {
    let mut any = false;
    for relationship in &workspace.data.relationships {
        let from = workspace.entity(relationship.from_id);
        let to = workspace.entity(relationship.to_id);
        let Some(from) = from else { continue };
        let Some(to) = to else { continue };
        if !matches!(
            from.kind,
            crate::model::EntityKind::Domain
                | crate::model::EntityKind::Hostname
                | crate::model::EntityKind::Ip
                | crate::model::EntityKind::Url
                | crate::model::EntityKind::Asn
        ) {
            continue;
        }
        out.push_str(&format!(
            "- {} {} --{}--> {} {}\n",
            from.short_ref(),
            from.display_name(),
            relationship.kind,
            to.short_ref(),
            to.display_name()
        ));
        any = true;
    }
    if !any {
        out.push_str("No infrastructure relationships recorded.\n");
    }
    out.push('\n');
}

pub fn render_json(workspace: &Workspace) -> Result<String, String> {
    serde_json::to_string_pretty(&workspace.data).map_err(|error| error.to_string())
}

pub fn write_report(
    workspace: &Workspace,
    files: &InvestigationFiles,
    format: &str,
) -> Result<StoredBlob, String> {
    files.ensure().map_err(|error| error.to_string())?;
    let (body, extension) = match format {
        "json" => (render_json(workspace)?, "json"),
        _ => (render_markdown(workspace), "md"),
    };
    let name = format!(
        "{}-{}.{}",
        sanitize_filename(&workspace.investigation().name),
        now().format("%Y%m%dT%H%M%S"),
        extension
    );
    files
        .write_text("reports", &name, &body)
        .map_err(|error| error.to_string())
}

#[allow(dead_code)]
pub fn report_hash(body: &str) -> String {
    sha256_hex(body.as_bytes())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Confidence, Investigation, InvestigationData, now};
    use uuid::Uuid;

    fn empty_workspace(name: &str) -> Workspace {
        let timestamp = now();
        Workspace::new(InvestigationData::empty(Investigation {
            id: Uuid::new_v4(),
            name: name.into(),
            description: "A test case.".into(),
            tags: Vec::new(),
            created_at: timestamp,
            updated_at: timestamp,
        }))
    }

    #[test]
    fn markdown_includes_required_sections() {
        let actual = render_markdown(&empty_workspace("Example Corp"));
        for heading in [
            "# Example Corp",
            "## Executive Summary",
            "## Scope",
            "## Diagnostics",
            "## Key Findings",
            "## Entities",
            "## Infrastructure",
            "## Changes",
            "## Timeline",
            "## Evidence",
            "## Open Questions",
            "## Analyst Notes",
            "## Sources",
            "AI inference (unverified)",
        ] {
            assert!(actual.contains(heading), "missing {heading}");
        }
    }

    #[test]
    fn json_round_trips_investigation_data() {
        let workspace = empty_workspace("Example Corp");
        let json = render_json(&workspace).expect("json");
        let data: InvestigationData = serde_json::from_str(&json).expect("parses");
        assert_eq!(data.investigation.name, "Example Corp");
    }

    #[test]
    fn agent_findings_are_labelled() {
        use crate::model::Finding;
        let mut workspace = empty_workspace("Op");
        workspace.data.findings.push(Finding {
            id: Uuid::new_v4(),
            investigation_id: workspace.id(),
            seq: 1,
            page_id: None,
            title: "Cloudflare appears to terminate HTTP".into(),
            details: String::new(),
            confidence: Confidence::Medium,
            provenance: Provenance::Agent,
            source_ids: Vec::new(),
            created_at: now(),
            updated_at: now(),
        });
        let actual = render_markdown(&workspace);
        assert!(actual.contains("AI inference (unverified)"));
        assert!(actual.contains("*(none)*"));
    }
}
